"""Package approved-architecture HTML designs and actual browser posters for review."""
from pathlib import Path
import argparse, json, shutil

ROOT = Path(__file__).resolve().parents[1]
PUBLIC = ROOT / 'apps/web/public'

INDEX = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Commercial real estate · JLL & Meridian review</title><style>
*{box-sizing:border-box}body{margin:0;background:#f2f2ee;color:#15252a;font:16px/1.5 Arial,sans-serif}header{padding:40px 5vw 30px;border-bottom:1px solid #cbd2d2;background:white}.overline{font-size:12px;letter-spacing:.15em;text-transform:uppercase;color:#6b7578}h1{font-size:clamp(28px,4vw,52px);line-height:1.1;letter-spacing:-.04em;margin:10px 0 16px}header p{max-width:900px;margin:0;color:#536267}.toolbar{display:flex;gap:12px;flex-wrap:wrap;align-items:center;padding:24px 5vw}button,a{font:inherit}button{cursor:pointer;border:1px solid #b7c3c3;background:#fff;color:#15252a;padding:11px 18px;border-radius:3px}button:hover,button:focus-visible{border-color:#15252a;outline:2px solid #b2cdce;outline-offset:2px}button[aria-pressed=true]{background:#15252a;color:#fff}.toolbar span{margin-left:auto;color:#536267;font-size:13px}.workspace{display:grid;grid-template-columns:250px 1fr;gap:30px;margin:0 5vw 40px}nav{display:flex;flex-direction:column;gap:8px}nav button{text-align:left;font-size:14px}nav small{display:block;color:#728187}nav [aria-pressed=true] small{color:#d7e6e6}.boards{display:grid;grid-template-columns:1fr 1fr;gap:25px;align-items:start}.board h2{margin:0 0 14px;font-size:20px}.brand-tag{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:9px;background:#e30613}.generic .brand-tag{background:#0b4e51}.poster{width:100%;display:block;border:1px solid #d0d8d8;background:white;cursor:pointer}.live{width:100%;aspect-ratio:16/9;border:0;background:white;display:none}.portrait .live{aspect-ratio:9/16}.board-actions{display:flex;gap:10px;margin-top:12px;flex-wrap:wrap}.board-actions button{font-size:13px}.hint{font-size:13px;color:#536267;margin:18px 0 0}.info{background:#fff;border-top:1px solid #cbd2d2;padding:32px 5vw 50px;display:grid;grid-template-columns:1fr 1fr;gap:60px}.info h2{font-size:20px}.info p,.info li{color:#536267}.info li{margin:8px 0}.info a{color:#0b4e51}.overlay{position:fixed;top:0;left:0;width:100%;height:100%;background:#142127;z-index:50;padding:65px 20px 20px;display:flex;align-items:center;justify-content:center}.overlay[hidden]{display:none}.overlay iframe{width:min(calc((100vh - 95px)*16/9),calc(100vw - 40px));height:min(calc((100vw - 40px)*9/16),calc(100vh - 95px));border:0}.overlay.portrait iframe{width:min(calc((100vh - 95px)*9/16),calc(100vw - 40px));height:min(calc((100vw - 40px)*16/9),calc(100vh - 95px))}.overlay button{position:absolute;top:12px;right:20px;background:white}.sample-note{font-size:13px;margin:30px 0 0;color:#536267}@media(max-width:1000px){.workspace{grid-template-columns:1fr}nav{display:grid;grid-template-columns:1fr 1fr}.boards{grid-template-columns:1fr}.info{grid-template-columns:1fr}.toolbar span{width:100%;margin:0}}
</style></head><body><header><div class="overline">VenueOS · Design review · October 2026</div><h1>Commercial property, from first impression to full tour.</h1><p>Eight JLL designs and eight matching reusable designs. Each supports landscape and portrait, with two touch experiences for exploring the property and comparing opportunities.</p></header><div class="toolbar"><button data-orientation="LANDSCAPE" aria-pressed="true">Landscape</button><button data-orientation="PORTRAIT" aria-pressed="false">Portrait</button><span>32 formats · Existing CMS editing tools · Ready for review</span></div><div class="workspace"><nav aria-label="Template concepts"></nav><main><div class="boards"><section class="board jll"><h2><span class="brand-tag"></span>JLL</h2><img class="poster" alt="JLL template preview"><iframe class="live" title="JLL interactive preview" sandbox="allow-scripts"></iframe><div class="board-actions"><button data-live="jll">Try live preview</button><button data-full="jll">Open full preview</button></div></section><section class="board generic"><h2><span class="brand-tag"></span>Reusable · Meridian</h2><img class="poster" alt="Generic template preview"><iframe class="live" title="Generic interactive preview" sandbox="allow-scripts"></iframe><div class="board-actions"><button data-live="standard">Try live preview</button><button data-full="standard">Open full preview</button></div></section></div><p class="hint">Use the full preview to try touch navigation, plan zooming and property comparison. Escape closes the full preview.</p><p class="sample-note">Property names, measurements, drawings, financial metrics and contacts are illustrative. Replace them with approved property content before publication.</p></main></div><div class="info"><section><h2>Customize with the CMS tools you already have.</h2><ul><li>Edit property copy, specifications, suite availability and leasing terms.</li><li>Replace the logo, photography, maps and floor plans from the Media Library.</li><li>Change colors, fonts, type styles and saved text positions.</li><li>Reorder gallery photos, set timing, select single-image playback and adjust crop or containment.</li><li>Set broker contacts and the QR destination for brochures or tour requests.</li></ul><p>JLL templates stay scoped to the customer tenant. The generic set is registered for Corporate and Touch Kiosks.</p></section><section><h2>Built around JLL’s property information.</h2><p>Office leasing, amenity collections, floor plates, available suites, connectivity, industrial specifications and investment offerings are supported by dedicated layouts.</p><p>The guided tour covers eight sections. The finder includes Office, Industrial, Retail and Life science, property details and two-property comparison.</p><p>References: <a href="https://www.jll.com/en-us/">JLL</a> · <a href="https://property.jll.com/en-ca/listings/1-city-centre-drive">Office listing</a> · <a href="https://invest.jll.com/se/en/listings/industrial-logistics/19701-hamilton-ave">Industrial offering</a></p><p><a href="README.md">Handoff & customization notes</a></p></section></div><div class="overlay" role="dialog" aria-modal="true" aria-label="Full template preview" hidden><button data-close>Close preview</button><iframe title="Full interactive property preview" sandbox="allow-scripts"></iframe></div><script>
const records=RECORDS;
let orientation='LANDSCAPE',concept='01',returnFocus;
const nav=document.querySelector('nav'),overlay=document.querySelector('.overlay');
const names=['Property Overview','Amenity Collection','Floor Plans & Availability','Location & Connectivity','Industrial Specifications','Investment Offering','Guided Property Tour','Property Finder & Compare'];
names.forEach((name,i)=>{const b=document.createElement('button');b.dataset.concept=String(i+1).padStart(2,'0');b.textContent=name;const s=document.createElement('small');s.textContent=i>=6?'Interactive touch experience':'Property marketing signage';b.append(s);nav.append(b);});
function record(collection){return records.find(r=>r.collection===collection&&r.orientation===orientation&&r.url.split('/').pop().startsWith(concept));}
function url(r){return r.url.slice(1)+(r.url.includes('?')?'&':'?')+(r.category==='KIOSK'?'':'text=eyJjYXJvdXNlbC5hdXRvcGxheSI6Im5vIn0');}
function render(){document.querySelectorAll('[data-orientation]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.orientation===orientation));document.querySelectorAll('[data-concept]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.concept===concept));document.querySelector('.boards').classList.toggle('portrait',orientation==='PORTRAIT');['jll','standard'].forEach(c=>{const r=record(c),section=document.querySelector(c==='jll'?'.jll':'.generic'),poster=section.querySelector('.poster'),frame=section.querySelector('iframe'),slug=r.url.slice('/templates/'.length).split('?')[0].replace(/\.html$/,'');poster.src='templates/_thumbs/'+slug+(orientation==='PORTRAIT'?'-portrait':'')+'.png';poster.style.display='block';frame.style.display='none';frame.removeAttribute('src');section.querySelector('[data-live]').textContent='Try live preview';});}
function close(){overlay.hidden=true;overlay.querySelector('iframe').removeAttribute('src');returnFocus?.focus();}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.orientation){orientation=b.dataset.orientation;render();}if(b.dataset.concept){concept=b.dataset.concept;render();}if(b.dataset.live){if(location.protocol==='file:'){alert('For the live touch experience, run Launch Preview.command in this folder. Static posters are available here.');return;}const section=b.closest('.board'),frame=section.querySelector('iframe'),live=frame.style.display==='block';frame.style.display=live?'none':'block';section.querySelector('.poster').style.display=live?'block':'none';if(!live)frame.src=url(record(b.dataset.live));else frame.removeAttribute('src');b.textContent=live?'Try live preview':'Show poster';}if(b.dataset.full){if(location.protocol==='file:'){alert('For the live touch experience, run Launch Preview.command in this folder.');return;}returnFocus=b;overlay.classList.toggle('portrait',orientation==='PORTRAIT');overlay.querySelector('iframe').src=url(record(b.dataset.full));overlay.hidden=false;overlay.querySelector('button').focus();}if(b.hasAttribute('data-close'))close();});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!overlay.hidden)close();});
render();
</script></body></html>'''

def package(output):
    output.mkdir(parents=True, exist_ok=True)
    rows = json.loads((ROOT / 'docs/templates/commercial-real-estate-install-manifest.json').read_text())
    for folder in ['signage/corporate/commercial-real-estate', 'kiosk/commercial-real-estate', 'custom/jll-commercial-real-estate']:
        shutil.copytree(PUBLIC / 'templates' / folder, output / 'templates' / folder, dirs_exist_ok=True)
        shutil.copytree(PUBLIC / 'templates/_thumbs' / folder, output / 'templates/_thumbs' / folder, dirs_exist_ok=True)
    shutil.copy2(PUBLIC / 'templates/_native-image-carousel.js', output / 'templates/_native-image-carousel.js')
    shutil.copy2(ROOT / 'docs/templates/commercial-real-estate-install-manifest.json', output / 'manifest.json')
    shutil.copy2(ROOT / 'docs/templates/commercial-real-estate-installation.md', output / 'README.md')
    (output / 'index.html').write_text(INDEX.replace('RECORDS', json.dumps(rows)))
    launcher = output / 'Launch Preview.command'
    launcher.write_text('#!/bin/zsh\ncd -- "${0:A:h}"\nopen "http://127.0.0.1:8926/index.html"\npython3 -m http.server 8926 --bind 127.0.0.1\n')
    launcher.chmod(0o755)
    print(output)

if __name__ == '__main__':
    p = argparse.ArgumentParser(); p.add_argument('--output', type=Path, default=Path('/tmp/commercial-real-estate-review'))
    package(p.parse_args().output.expanduser().resolve())
